1	using System.Globalization;
2	using Microsoft.Net.Http.Headers;
3	using TutorFlow.Core.Asistente;
4	using TutorFlow.Core.Autorizacion;
5	
6	namespace TutorFlow.Api;
7	
8	public sealed partial class ProcesadorPregunta
9	{
10	    private const string TipoDeContenidoJson = "application/json";
11	    private const string IpDesconocida = "desconocida";
12	    private const string TituloTipoNoSoportado = "El tipo de contenido de la solicitud no está soportado.";
13	    private const string TituloSolicitudInvalida = "La solicitud no es válida.";
14	    private const string TituloCuerpoDemasiadoGrande = "El cuerpo de la solicitud supera el tamaño permitido.";
15	    private const string TituloDemasiadasSolicitudes = "Se superó el límite de preguntas. Intenta de nuevo más tarde.";
16	    private const string TituloServicioNoDisponible = "El servicio no está disponible en este momento. Intenta de nuevo.";
17	
18	    private readonly LimitesAsistente _limites;
19	    private readonly LimitadorTasaPorIp _limitadorTasa;
20	    private readonly IReloj _reloj;
21	    private readonly TimeProvider _tiempo;
22	    private readonly AuditorPeticiones _auditor;
23	    private readonly PreguntarAsistente _preguntarAsistente;
24	    private readonly ILogger<ProcesadorPregunta> _logger;
25	
26	    public ProcesadorPregunta(
27	        LimitesAsistente limites,
28	        LimitadorTasaPorIp limitadorTasa,
29	        IReloj reloj,
30	        TimeProvider tiempo,
31	        AuditorPeticiones auditor,
32	        PreguntarAsistente preguntarAsistente,
33	        ILogger<ProcesadorPregunta> logger)
34	    {
35	        _limites = limites;
36	        _limitadorTasa = limitadorTasa;
37	        _reloj = reloj;
38	        _tiempo = tiempo;
39	        _auditor = auditor;
40	        _preguntarAsistente = preguntarAsistente;
41	        _logger = logger;
42	    }
43	
44	    public async Task<IResult> ProcesarAsync(HttpContext contexto, CancellationToken cancellationToken)
45	    {
46	        var peticion = new DatosPeticion(IpDe(contexto), contexto.TraceIdentifier, _tiempo.GetTimestamp());
47	        var tasa = _limitadorTasa.Intentar(peticion.Ip);
48	        return tasa.Permitido
49	            ? await ProcesarEntradaAsync(contexto, peticion, cancellationToken)
50	            : await RechazarPorTasaAsync(contexto, peticion, tasa.SegundosParaReintentar, cancellationToken);
51	    }
52	
53	    private async Task<IResult> ProcesarEntradaAsync(HttpContext contexto, DatosPeticion peticion, CancellationToken cancellationToken)
54	    {
55	        if (!EsJson(contexto.Request.ContentType))
56	        {
57	            return RechazarInvalida(peticion, null, StatusCodes.Status415UnsupportedMediaType, TituloTipoNoSoportado);
58	        }
59	
60	        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
61	        if (cuerpo.ExcedeElLimite)
62	        {
63	            return RechazarInvalida(peticion, null, StatusCodes.Status413PayloadTooLarge, TituloCuerpoDemasiadoGrande);
64	        }
65	
66	        var solicitud = ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
67	        return solicitud.EsValida
68	            ? await ResponderAsync(contexto, peticion, solicitud, cancellationToken)
69	            : RechazarInvalida(peticion, solicitud.Pregunta, StatusCodes.Status400BadRequest, TituloSolicitudInvalida);
70	    }
71	
72	    private async Task<IResult> RechazarPorTasaAsync(HttpContext contexto, DatosPeticion peticion, int segundosParaReintentar, CancellationToken cancellationToken)
73	    {
74	        var solicitud = await LeerSolicitudParaAuditoriaAsync(contexto, cancellationToken);
75	        return Rechazar429(contexto, peticion, solicitud, segundosParaReintentar);
76	    }
77	
78	    private async Task<SolicitudValidada?> LeerSolicitudParaAuditoriaAsync(HttpContext contexto, CancellationToken cancellationToken)
79	    {
80	        if (!EsJson(contexto.Request.ContentType))
81	        {
82	            return null;
83	        }
84	
85	        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
86	        return cuerpo.ExcedeElLimite ? null : ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
87	    }
88	
89	    private static bool EsJson(string? tipoDeContenido) =>
90	        MediaTypeHeaderValue.TryParse(tipoDeContenido, out var tipo)
91	        && string.Equals(tipo.MediaType.Value, TipoDeContenidoJson, StringComparison.OrdinalIgnoreCase);
92	
93	    private static string IpDe(HttpContext contexto)
94	    {
95	        var direccion = contexto.Connection.RemoteIpAddress;
96	        if (direccion is null)
97	        {
98	            return IpDesconocida;
99	        }
100	
101	        return (direccion.IsIPv4MappedToIPv6 ? direccion.MapToIPv4() : direccion).ToString();
102	    }
103	
104	    private async Task<IResult> ResponderAsync(HttpContext contexto, DatosPeticion peticion, SolicitudValidada solicitud, CancellationToken cancellationToken)
105	    {
106	        var usuario = new Usuario(solicitud.Rol!.Value, solicitud.UsuarioId!);
107	        return await PreguntarAsync(contexto, peticion, new PreguntaEntrada(solicitud.Pregunta!, usuario), cancellationToken);
108	    }
109	
110	    private async Task<IResult> PreguntarAsync(HttpContext contexto, DatosPeticion peticion, PreguntaEntrada entrada, CancellationToken cancellationToken)
111	    {
112	        try
113	        {
114	            var resultado = await _preguntarAsistente.EjecutarAsync(entrada, peticion.Ip, peticion.CorrelationId, cancellationToken);
115	            return Mapear(contexto, resultado);
116	        }
117	        catch (Exception excepcion) when (EsFalloDeDependencia(excepcion, cancellationToken))
118	        {
119	            RegistrarDependenciaCaida(_logger, excepcion.GetType().Name);
120	            return Responder503(contexto, SegundosDelProveedor(excepcion));
121	        }
122	    }
123	
124	    private int SegundosDelProveedor(Exception excepcion) =>
125	        excepcion is DependenciaNoDisponibleException dependencia
126	            ? RetryAfterDelProveedor.Segundos(dependencia.RetryAfterDelProveedor, _reloj.AhoraUtc) ?? 0
127	            : 0;
128	
129	    private static bool EsFalloDeDependencia(Exception excepcion, CancellationToken cancellationToken) =>
130	        excepcion is DependenciaNoDisponibleException or HttpRequestException or TimeoutException
131	        || (excepcion is OperationCanceledException && !cancellationToken.IsCancellationRequested);
132	
133	    private static IResult Mapear(HttpContext contexto, ResultadoPregunta resultado)
134	    {
135	        if (resultado.Respuesta is not { } respuesta)
136	        {
137	            return Responder503(contexto, resultado.SegundosParaReintentar);
138	        }
139	
140	        var cuerpo = new PreguntaRespuesta(
141	            respuesta.Respuesta,
142	            [.. respuesta.Citas.Select(cita => new CitaRespuesta(cita.Documento, cita.Seccion))],
143	            respuesta.UsoDatosEstudiante,
144	            respuesta.Tokens,
145	            respuesta.CostoUsd);
146	        var estado = resultado.Tipo == TipoResultadoPregunta.Denegada ? StatusCodes.Status403Forbidden : StatusCodes.Status200OK;
147	        return Results.Json(cuerpo, statusCode: estado);
148	    }
149	
150	    private IResult RechazarInvalida(DatosPeticion peticion, string? pregunta, int estado, string titulo)
151	    {
152	        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
153	            peticion.Ip,
154	            peticion.CorrelationId,
155	            null,
156	            null,
157	            pregunta,
158	            ResultadoAuditoria.Invalida,
159	            Milisegundos(peticion)));
160	        return Results.Problem(statusCode: estado, title: titulo);
161	    }
162	
163	    private IResult Rechazar429(HttpContext contexto, DatosPeticion peticion, SolicitudValidada? solicitud, int segundosParaReintentar)
164	    {
165	        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
166	            peticion.Ip,
167	            peticion.CorrelationId,
168	            solicitud?.Rol,
169	            solicitud?.UsuarioId,
170	            solicitud?.Pregunta,
171	            ResultadoAuditoria.Denegada,
172	            Milisegundos(peticion)));
173	        return Responder429(contexto, segundosParaReintentar);
174	    }
175	
176	    private static IResult Responder503(HttpContext contexto, int segundosParaReintentar)
177	    {
178	        if (segundosParaReintentar > 0)
179	        {
180	            contexto.Response.Headers.RetryAfter = segundosParaReintentar.ToString(CultureInfo.InvariantCulture);
181	        }
182	
183	        return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
184	    }
185	
186	    private static IResult Responder429(HttpContext contexto, int segundosParaReintentar)
187	    {
188	        contexto.Response.Headers.RetryAfter = segundosParaReintentar.ToString(CultureInfo.InvariantCulture);
189	        return Results.Problem(statusCode: StatusCodes.Status429TooManyRequests, title: TituloDemasiadasSolicitudes);
190	    }
191	
192	    [LoggerMessage(Level = LogLevel.Warning, Message = "Una dependencia no respondió ({TipoDeError}).")]
193	    private static partial void RegistrarDependenciaCaida(ILogger logger, string tipoDeError);
194	
195	    private long Milisegundos(DatosPeticion peticion) =>
196	        (long)_tiempo.GetElapsedTime(peticion.InicioTimestamp).TotalMilliseconds;
197	
198	    private sealed record DatosPeticion(string Ip, string CorrelationId, long InicioTimestamp);
199	}
200

