1	namespace TutorFlow.Api;
2	
3	public sealed record ResultadoTasa(bool Permitido, int SegundosParaReintentar);
4	
5	public sealed class LimitadorTasaPorIp
6	{
7	    private const int UmbralDeLimpieza = 10_000;
8	    private const int SegundosDeVentana = 60;
9	    private const int SegundosDeReinicio = 600;
10	    private const int SegundosDelPrimerBloqueo = 30;
11	    private const int NivelMaximo = 3;
12	
13	    private readonly Lock _candado = new();
14	    private readonly Dictionary<string, EstadoDeIp> _porIp = [];
15	    private readonly int _limite;
16	    private readonly TimeProvider _tiempo;
17	
18	    public LimitadorTasaPorIp(int limite, TimeProvider tiempo)
19	    {
20	        _limite = limite;
21	        _tiempo = tiempo;
22	    }
23	
24	    public ResultadoTasa Intentar(string ip)
25	    {
26	        lock (_candado)
27	        {
28	            var ahora = _tiempo.GetUtcNow();
29	            PurgarSiHaceFalta(ahora);
30	            if (!_porIp.TryGetValue(ip, out var estado))
31	            {
32	                estado = new EstadoDeIp();
33	                _porIp[ip] = estado;
34	            }
35	
36	            return Decidir(estado, ahora);
37	        }
38	    }
39	
40	    private ResultadoTasa Decidir(EstadoDeIp estado, DateTimeOffset ahora)
41	    {
42	        if (ahora < estado.BloqueadaHasta)
43	        {
44	            return Denegado(SegundosRestantes(estado.BloqueadaHasta, ahora));
45	        }
46	
47	        estado.DescartarMarcasFueraDeVentana(ahora);
48	        if (estado.Marcas.Count < _limite)
49	        {
50	            estado.Marcas.Enqueue(ahora);
51	            return new ResultadoTasa(true, 0);
52	        }
53	
54	        return Bloquear(estado, ahora);
55	    }
56	
57	    private static ResultadoTasa Bloquear(EstadoDeIp estado, DateTimeOffset ahora)
58	    {
59	        estado.Marcas.Clear();
60	        var reinicia = estado.FinUltimoBloqueo is not { } fin || (ahora - fin).TotalSeconds >= SegundosDeReinicio;
61	        estado.Nivel = reinicia ? 1 : Math.Min(estado.Nivel + 1, NivelMaximo);
62	        var duracion = SegundosDelPrimerBloqueo << (estado.Nivel - 1);
63	        estado.BloqueadaHasta = ahora.AddSeconds(duracion);
64	        estado.FinUltimoBloqueo = estado.BloqueadaHasta;
65	        return Denegado(duracion);
66	    }
67	
68	    private static ResultadoTasa Denegado(int segundos) => new(false, segundos);
69	
70	    private static int SegundosRestantes(DateTimeOffset hasta, DateTimeOffset ahora) =>
71	        Math.Max(1, (int)Math.Ceiling((hasta - ahora).TotalSeconds));
72	
73	    private void PurgarSiHaceFalta(DateTimeOffset ahora)
74	    {
75	        if (_porIp.Count < UmbralDeLimpieza)
76	        {
77	            return;
78	        }
79	
80	        foreach (var (ip, estado) in _porIp.ToList())
81	        {
82	            if (estado.EstaInactivo(ahora))
83	            {
84	                _porIp.Remove(ip);
85	            }
86	        }
87	    }
88	
89	    private sealed class EstadoDeIp
90	    {
91	        public Queue<DateTimeOffset> Marcas { get; } = new();
92	
93	        public int Nivel { get; set; }
94	
95	        public DateTimeOffset BloqueadaHasta { get; set; }
96	
97	        public DateTimeOffset? FinUltimoBloqueo { get; set; }
98	
99	        public void DescartarMarcasFueraDeVentana(DateTimeOffset ahora)
100	        {
101	            while (Marcas.Count > 0 && (ahora - Marcas.Peek()).TotalSeconds >= SegundosDeVentana)
102	            {
103	                Marcas.Dequeue();
104	            }
105	        }
106	
107	        public bool EstaInactivo(DateTimeOffset ahora)
108	        {
109	            DescartarMarcasFueraDeVentana(ahora);
110	            var sinBloqueoReciente = FinUltimoBloqueo is not { } fin || (ahora - fin).TotalSeconds >= SegundosDeReinicio;
111	            return Marcas.Count == 0 && sinBloqueoReciente;
112	        }
113	    }
114	}
