1	using System.Globalization;
2	using Microsoft.AspNetCore.Hosting;
3	using System.Net;
4	using System.Text.Encodings.Web;
5	using Microsoft.Extensions.Http;
6	using Microsoft.Extensions.Options;
7	using TutorFlow.Core.Asistente;
8	using TutorFlow.Core.Autorizacion;
9	using TutorFlow.Infrastructure.ApiAcademica;
10	using TutorFlow.Infrastructure.Auditoria;
11	using TutorFlow.Infrastructure.Configuracion;
12	using TutorFlow.Infrastructure.Conocimiento;
13	using TutorFlow.Infrastructure.Llm;
14	using TutorFlow.Infrastructure.Tiempo;
15	
16	namespace TutorFlow.Api;
17	
18	public static class ServiciosTutorFlow
19	{
20	    private const string NombreClienteLlm = "llm";
21	    private const string SeccionAsignaturas = "Autorizacion:Asignaturas";
22	    private const string ClaveMarcadorCanario = "Llm:MarcadorCanario";
23	    private const string ClaveReservaPorPeticion = "Llm:ReservaPorPeticionUsd";
24	    private const string ClaveReservaSinPrecio = "Llm:ReservaSinPrecioUsd";
25	    private const string ClaveRelevanciaMinima = "Conocimiento:RelevanciaMinima";
26	    private const string ClaveApoyoMinimoRespaldo = "Conocimiento:ApoyoMinimoRespaldo";
27	    private const string ClavePuntajeRelativoMinimo = "Conocimiento:PuntajeRelativoMinimo";
28	    private const string ClavePuntajeRelativoRelevante = "Conocimiento:PuntajeRelativoRelevante";
29	    private const int PuntajeRelativoMinimoPorDefecto = 55;
30	    private const int PuntajeRelativoRelevantePorDefecto = 40;
31	    private const string ClaveTemperatura = "Llm:Temperatura";
32	    private const string ClaveSemilla = "Llm:Semilla";
33	    private const int SemillaPorDefecto = 1;
34	    internal const string ClaveSeccionLimites = "Limites";
35	    private const string ClaveTraceId = "traceId";
36	    private const string VariableLlaveLlm = "LLM_API_KEY";
37	
38	    public static IServiceCollection AgregarTutorFlow(this IServiceCollection servicios, IConfiguration configuracion)
39	    {
40	        servicios.AddTransient<IStartupFilter, ValidacionDeArranque>();
41	        AgregarOpciones(servicios);
42	        AgregarNucleo(servicios, configuracion);
43	        AgregarInfraestructura(servicios, configuracion);
44	        AgregarLlm(servicios, configuracion);
45	        servicios.AddProblemDetails(opciones =>
46	            opciones.CustomizeProblemDetails = contexto => contexto.ProblemDetails.Extensions[ClaveTraceId] = contexto.HttpContext.TraceIdentifier);
47	        servicios.AddExceptionHandler<ManejadorExcepciones>();
48	        servicios.ConfigureHttpJsonOptions(opciones => opciones.SerializerOptions.Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping);
49	        servicios.AddHostedService<RegistroArranqueLlm>();
50	        return servicios;
51	    }
52	
53	    private static void AgregarOpciones(IServiceCollection servicios)
54	    {
55	        servicios.AddOptions<OpcionesApiAcademica>()
56	            .BindConfiguration(OpcionesApiAcademica.Seccion)
57	            .Validate(o => Uri.IsWellFormedUriString(o.UrlBase, UriKind.Absolute), "ApiAcademica:UrlBase debe ser una URL absoluta")
58	            .ValidateOnStart();
59	        servicios.AddOptions<OpcionesLlm>()
60	            .BindConfiguration(OpcionesLlm.Seccion)
61	            .Validate(o => o.Proveedores.Count > 0, "Llm:Proveedores no puede estar vacio");
62	        servicios.AddOptions<LimitesAsistente>()
63	            .Configure<IConfiguration>(EnlazadorDeLimites.Enlazar)
64	            .Validate(l => l.MaximoCaracteresPregunta > 0 && l.PreguntasPorMinutoPorIp > 0, "Limites invalidos");
65	        servicios.AddOptions<OpcionesConocimiento>()
66	            .BindConfiguration(OpcionesConocimiento.Seccion)
67	            .Validate(o => o.DocumentosVigentes.Count > 0, "Conocimiento:DocumentosVigentes no puede estar vacio")
68	            .ValidateOnStart();
69	    }
70	
71	    private static void AgregarNucleo(IServiceCollection servicios, IConfiguration configuracion)
72	    {
73	        servicios.AddSingleton(proveedor => proveedor.GetRequiredService<IOptions<LimitesAsistente>>().Value);
74	        servicios.AddSingleton<PoliticaAcceso>();
75	        servicios.AddSingleton<VerificadorSalida>();
76	        servicios.AddSingleton<AuditorPeticiones>();
77	        servicios.AddSingleton<PresupuestoDiario>();
78	        servicios.AddSingleton<LimitadorIdentidades>();
79	        servicios.AddSingleton(proveedor => new LimitadorTasaPorIp(
80	            proveedor.GetRequiredService<LimitesAsistente>().PreguntasPorMinutoPorIp,
81	            proveedor.GetRequiredService<TimeProvider>()));
82	        servicios.AddSingleton(proveedor => ConfiguracionDelAsistente(proveedor, configuracion));
83	        servicios.AddScoped<PreguntarAsistente>();
84	        servicios.AddScoped<ProcesadorPregunta>();
85	    }
86	
87	    private static void AgregarInfraestructura(IServiceCollection servicios, IConfiguration configuracion)
88	    {
89	        servicios.AddSingleton(TimeProvider.System);
90	        servicios.AddSingleton<IReloj, RelojSistema>();
91	        servicios.AddSingleton(proveedor => new ArchivoAuditoriaDiario(
92	            configuracion[ArchivoAuditoriaDiario.ClaveRuta],
93	            proveedor.GetRequiredService<IReloj>()));
94	        servicios.AddSingleton<IAuditoria, AuditoriaJsonConsola>();
95	        servicios.AddSingleton<IBaseConocimiento>(proveedor =>
96	            CargadorConocimiento.Cargar(proveedor.GetRequiredService<IOptions<OpcionesConocimiento>>().Value, UmbralesDeEntregaDe(configuracion)));
97	        servicios.AddHttpClient<IApiAcademica, ClienteApiAcademica>((proveedor, cliente) =>
98	            {
99	                var opciones = proveedor.GetRequiredService<IOptions<OpcionesApiAcademica>>().Value;
100	                cliente.BaseAddress = new Uri(opciones.UrlBase.TrimEnd('/') + "/");
101	                cliente.Timeout = TimeSpan.FromSeconds(proveedor.GetRequiredService<LimitesAsistente>().PresupuestoApiAcademicaSegundos);
102	            })
103	            .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { AllowAutoRedirect = false });
104	    }
105	
106	    private static void AgregarLlm(IServiceCollection servicios, IConfiguration configuracion)
107	    {
108	        servicios.AddSingleton<IVariablesEntorno, VariablesEntornoProceso>();
109	        servicios.AddSingleton(proveedor => ResolutorProveedorLlm.Resolver(
