112	        servicios.AddHttpClient(NombreClienteLlm)
113	            .ConfigureHttpClient((proveedor, cliente) =>
114	                cliente.Timeout = TimeSpan.FromSeconds(proveedor.GetRequiredService<LimitesAsistente>().TimeoutLlmSegundos));
