157	        new(
158	            Entero(configuracion, ClavePuntajeRelativoMinimo, PuntajeRelativoMinimoPorDefecto),
159	            Entero(configuracion, ClavePuntajeRelativoRelevante, PuntajeRelativoRelevantePorDefecto),
160	            Entero(configuracion, ClaveRelevanciaMinima, ConfiguracionAsistente.RelevanciaMinimaPorDefecto));
