162	    internal static AjustesDelModelo AjustesDelModelo(IConfiguration configuracion) =>
163	        new(
164	            ValidadorDeConfiguracion.Efectivo(configuracion, ClaveTemperatura) ?? 0m,
165	            Entero(configuracion, ClaveSemilla, SemillaPorDefecto));
