31	public sealed class PreguntarAsistente
32	{
33	    private readonly DependenciasDeAsistente _dependencias;
34	    private readonly LimitadorIdentidades? _limitadorIdentidades;
35	    private readonly LectorResumenPropio _lectorResumen;
36	    private readonly RelevanciaPrevia _relevancia;
37	    private readonly EmisorDeResultados _emisor;
38	    private readonly FaseDelModelo _fase;
39	    private readonly TimeProvider _tiempo;
40	
41	    public PreguntarAsistente(
42	        IApiAcademica apiAcademica,
43	        IClienteLlm clienteLlm,
44	        IBaseConocimiento baseConocimiento,
45	        AuditorPeticiones auditor,
46	        PoliticaAcceso politicaAcceso,
47	        VerificadorSalida verificadorSalida,
48	        LimitesAsistente limites,
49	        ConfiguracionAsistente configuracion,
50	        PresupuestoDiario presupuesto,
51	        LimitadorIdentidades? limitadorIdentidades = null,
52	        TimeProvider? tiempo = null)
53	        : this(
54	            new DependenciasDeAsistente(apiAcademica, clienteLlm, baseConocimiento, auditor, politicaAcceso, verificadorSalida, limites, configuracion, presupuesto),
55	            limitadorIdentidades,
56	            tiempo ?? TimeProvider.System)
57	    {
58	    }
59	
60	    private PreguntarAsistente(DependenciasDeAsistente dependencias, LimitadorIdentidades? limitadorIdentidades, TimeProvider tiempo)
61	    {
62	        _tiempo = tiempo;
63	        _dependencias = dependencias;
64	        _limitadorIdentidades = limitadorIdentidades;
65	        _lectorResumen = new LectorResumenPropio(dependencias.PoliticaAcceso);
66	        _relevancia = new RelevanciaPrevia(dependencias.PoliticaAcceso, dependencias.Configuracion.RelevanciaMinima);
67	        _emisor = new EmisorDeResultados(dependencias.Auditor, dependencias.PoliticaAcceso, dependencias.Configuracion);
68	        _fase = FaseDelModelo.Ensamblar(dependencias, _emisor);
69	    }
70	
71	    public async Task<ResultadoPregunta> EjecutarAsync(
72	        PreguntaEntrada entrada,
73	        string ipOrigen,
74	        string correlationId,
75	        CancellationToken cancellationToken)
76	    {
77	        var presupuestoApi = TimeSpan.FromSeconds(_dependencias.Limites.PresupuestoApiAcademicaSegundos);
78	        var api = new ApiAcademicaConPresupuesto(_dependencias.ApiAcademica, presupuestoApi, _tiempo);
79	        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, api, _tiempo);
80	        try
81	        {
82	            return await ResponderSesionAsync(sesion, cancellationToken);
83	        }
84	        catch (Exception)
85	        {
86	            _emisor.Auditar(sesion, ResultadoAuditoria.Error, null, []);
87	            throw;
88	        }
89	    }
90	
91	    private async Task<ResultadoPregunta> ResponderSesionAsync(SesionPregunta sesion, CancellationToken cancellationToken)
92	    {
93	        var directorio = await ConstructorDirectorio.ConstruirAsync(sesion.Entrada.Usuario, sesion.Api, _dependencias.Configuracion.CodigosAsignatura, cancellationToken);
94	        if (directorio is not null)
95	        {
96	            _dependencias.Auditor.RecordarPersonas(directorio);
97	            sesion.Directorio = ExcluirCodigosDePersonas(directorio);
98	        }
99	
100	        var identidad = _dependencias.PoliticaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, sesion.Directorio);
101	        if (!identidad.Permitido)
102	        {
103	            return _emisor.Denegar(sesion, identidad.Motivo, 0);
104	        }
105	
106	        AuditarIdentidades(sesion);
107	        return await ResponderSiEstaAutorizadoAsync(sesion, cancellationToken);
108	    }
109	
110	    private async Task<ResultadoPregunta> ResponderSiEstaAutorizadoAsync(SesionPregunta sesion, CancellationToken cancellationToken)
111	    {
112	        var decision = _dependencias.PoliticaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, sesion.Directorio);
113	        return decision.Permitido
114	            ? await ResponderSiEsRelevanteAsync(sesion, cancellationToken)
115	            : _emisor.Denegar(sesion, decision.Motivo, 0);
116	    }
117	
118	    private void AuditarIdentidades(SesionPregunta sesion)
119	    {
120	        var identidades = _limitadorIdentidades?.Registrar(sesion.IpOrigen, sesion.Entrada.Usuario.Id);
121	        if (identidades is { SuperacionNueva: true })
122	        {
123	            _dependencias.Auditor.RegistrarMultiplesIdentidades(sesion.IpOrigen, identidades.Ids);
124	        }
125	    }
126	
127	    private DirectorioAcademico ExcluirCodigosDePersonas(DirectorioAcademico directorio)
128	    {
129	        var catalogo = _dependencias.Configuracion.Catalogo;
130	        for (var indice = 0; indice < catalogo.Count; indice++)
131	        {
132	            if (CatalogoAsignaturas.EsIdDePersona(catalogo[indice].Codigo, directorio))
133	            {
134	                _dependencias.Configuracion.AdvertirUnaVez($"{Textos.PrefijoConfiguracionIgnorada}: Autorizacion:Asignaturas:{indice}:Codigo = \"{catalogo[indice].Codigo}\" (coincide con el ID de una persona del registro); se excluye del catálogo");
135	            }
136	        }
137	
138	        return directorio with { CodigosAsignatura = [.. directorio.CodigosAsignatura.Where(codigo => !CatalogoAsignaturas.EsIdDePersona(codigo, directorio))] };
139	    }
140	
141	    private async Task<ResultadoPregunta> ResponderSiEsRelevanteAsync(SesionPregunta sesion, CancellationToken cancellationToken)
142	    {
143	        var pregunta = sesion.Entrada.Pregunta;
144	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
145	        var recuperadas = _dependencias.BaseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(pregunta), _dependencias.Limites.MaximoSeccionesRecuperadas);
146	        sesion.Secciones = SeccionDeDerogacion.Agregar(recuperadas, pregunta, _dependencias.BaseConocimiento);
147	        var activacion = ActivadorResumenPropio.Evaluar(contexto, pregunta, CatalogoAsignaturas.Vigente(_dependencias.Configuracion.Catalogo, sesion.Directorio));
148	        if (_relevancia.PeriodoNoDisponible(contexto, pregunta, activacion))
149	        {
150	            return _emisor.SinInformacion(sesion);
151	        }
152	
153	        sesion.Activacion = await _lectorResumen.VerificarMatriculaAsync(contexto, activacion, sesion.Api, sesion.Registro, cancellationToken);
154	        return _relevancia.DebeResponderSinInformacion(contexto, pregunta, sesion.Secciones, sesion.Activacion)
155	            ? _emisor.SinInformacion(sesion)
156	            : await ResponderConReservaAsync(sesion, cancellationToken);
157	    }
158	
159	    private async Task<ResultadoPregunta> ResponderConReservaAsync(SesionPregunta sesion, CancellationToken cancellationToken)
160	    {
161	        var reserva = _dependencias.Configuracion.ReservaPorPeticionUsd;
162	        if (!_dependencias.Presupuesto.TryReservar(reserva))
163	        {
164	            return _emisor.NoDisponible(sesion, ResultadoAuditoria.Error) with { SegundosParaReintentar = _dependencias.Presupuesto.SegundosHastaElReinicio() };
165	        }
166	
167	        sesion.ReservaHecha = true;
168	        try
169	        {
170	            return await ResponderConTimeoutAsync(sesion, cancellationToken);
171	        }
172	        finally
173	        {
174	            Sustituir(sesion, reserva);
175	        }
176	    }
177	
178	    private void Sustituir(SesionPregunta sesion, decimal reserva)
179	    {
180	        _dependencias.Presupuesto.Sustituir(reserva, _dependencias.Configuracion.GastoDe(sesion.Uso.Valor, 1 + sesion.ReservasExtra));
181	        for (var extra = 0; extra < sesion.ReservasExtra; extra++)
182	        {
183	            _dependencias.Presupuesto.Sustituir(reserva, 0m);
184	        }
185	    }
186	
187	    private async Task<ResultadoPregunta> ResponderConTimeoutAsync(SesionPregunta sesion, CancellationToken cancellationToken)
188	    {
189	        using var temporizador = new CancellationTokenSource(TimeSpan.FromSeconds(_dependencias.Limites.TimeoutLlmSegundos), _tiempo);
190	        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, temporizador.Token);
191	        try
192	        {
193	            return await _fase.ResponderAsync(sesion, limite.Token, cancellationToken);
194	        }
195	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
196	        {
197	            throw new DependenciaNoDisponibleException("El tiempo total de la petición se agotó.");
198	        }
199	    }
200	}
