        this with
        {
            Notas = Notas
                .Select(n => n.EstudianteId == estudianteId && n.Notas.Codigo == codigo
                    ? n with { Notas = n.Notas with { Nombre = nombre } }
                    : n)
                .ToList()
        };
}

