27	    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeEstudiante =
28	    [
29	        new(Notas, "Consulta las definitivas de cada asignatura, el promedio ponderado del periodo, la prueba académica, la habilitación y la elegibilidad de beca de la persona que pregunta, ya calculados. Úsala para preguntas sobre notas, promedio, asignaturas perdidas, habilitación o beca.", []),
30	        new(Asistencia, "Consulta las inasistencias, las faltas permitidas y las faltas restantes de cada asignatura de la persona que pregunta. Úsala para preguntas sobre asistencia o faltas.", []),
31	        new(DatosBasicos, "Consulta el nombre, el programa y el coordinador del programa de la persona que pregunta. Úsala para preguntas sobre quién es su coordinador o a qué programa pertenece.", []),
32	        new(Cortes, "Consulta las notas de los tres cortes de una asignatura de la persona que pregunta. Úsala solo cuando pregunten por la nota de un corte concreto.", [new ParametroHerramienta(ParametroAsignatura, "Nombre o código de la asignatura.", true)])
33	    ];
