38	        new(Estudiante, "Consulta el detalle de notas y asistencia de un estudiante de los programas del coordinador. Úsala cuando pregunten por un estudiante concreto.", [new ParametroHerramienta(ParametroEstudianteId, "Identificador del estudiante: las letras EST, un guion y tres dígitos.", true)])
39	    ];
