41	    private readonly IApiAcademica _apiAcademica;
42	    private readonly PoliticaAcceso _politicaAcceso;
43	    private readonly Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>> _manejadores;
44	
45	    public HerramientasAsistente(IApiAcademica apiAcademica, PoliticaAcceso politicaAcceso)
46	    {
47	        _apiAcademica = apiAcademica;
48	        _politicaAcceso = politicaAcceso;
49	        _manejadores = new Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>>
50	        {
51	            [DatosBasicos] = ConsultarDatosBasicos,
