10	{
11	    public static ResultadoHerramienta Texto(string contenido) => new(contenido, false);
12	
13	    public static ResultadoHerramienta Denegado(string idSolicitado) => new(string.Empty, true, idSolicitado);
14	}
15	
16	public sealed class HerramientasAsistente
17	{
18	    public const string DatosBasicos = "consultar_datos_basicos";
19	    public const string Notas = "consultar_notas";
20	    public const string Cortes = "consultar_cortes";
21	    public const string Asistencia = "consultar_asistencia";
22	    public const string Programa = "consultar_programa";
23	    public const string Estudiante = "consultar_estudiante";
24	    public const string ParametroEstudianteId = "estudianteId";
25	    public const string ParametroAsignatura = "asignatura";
26	
27	    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeEstudiante =
28	    [
29	        new(Notas, "Consulta las definitivas de cada asignatura, el promedio ponderado del periodo, la prueba académica, la habilitación y la elegibilidad de beca de la persona que pregunta, ya calculados. Úsala para preguntas sobre notas, promedio, asignaturas perdidas, habilitación o beca.", []),
30	        new(Asistencia, "Consulta las inasistencias, las faltas permitidas y las faltas restantes de cada asignatura de la persona que pregunta. Úsala para preguntas sobre asistencia o faltas.", []),
31	        new(DatosBasicos, "Consulta el nombre, el programa y el coordinador del programa de la persona que pregunta. Úsala para preguntas sobre quién es su coordinador o a qué programa pertenece.", []),
32	        new(Cortes, "Consulta las notas de los tres cortes de una asignatura de la persona que pregunta. Úsala solo cuando pregunten por la nota de un corte concreto.", [new ParametroHerramienta(ParametroAsignatura, "Nombre o código de la asignatura.", true)])
33	    ];
34	
35	    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeCoordinador =
36	    [
37	        new(Programa, "Consulta, para cada estudiante de los programas a cargo del coordinador, el promedio, la prueba académica, las asignaturas perdidas, las asignaturas sin definitiva y la asistencia sin registro. Úsala para listados y conteos del programa.", []),
38	        new(Estudiante, "Consulta el detalle de notas y asistencia de un estudiante de los programas del coordinador. Úsala cuando pregunten por un estudiante concreto.", [new ParametroHerramienta(ParametroEstudianteId, "Identificador del estudiante: las letras EST, un guion y tres dígitos.", true)])
39	    ];
40	
41	    private readonly IApiAcademica _apiAcademica;
42	    private readonly PoliticaAcceso _politicaAcceso;
43	    private readonly Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>> _manejadores;
44	
45	    public HerramientasAsistente(IApiAcademica apiAcademica, PoliticaAcceso politicaAcceso)
46	    {
47	        _apiAcademica = apiAcademica;
48	        _politicaAcceso = politicaAcceso;
49	        _manejadores = new Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>>
50	        {
51	            [DatosBasicos] = ConsultarDatosBasicos,
52	            [Notas] = ConsultarNotas,
53	            [Cortes] = ConsultarCortes,
54	            [Asistencia] = ConsultarAsistencia,
55	            [Programa] = ConsultarPrograma,
56	            [Estudiante] = ConsultarEstudiante
57	        };
58	    }
59	
60	    public static IReadOnlyList<string> NombresInternos { get; } =
61	        [.. HerramientasDeEstudiante.Concat(HerramientasDeCoordinador).Select(herramienta => herramienta.Nombre)];
62	
63	    public static IReadOnlyList<HerramientaLlm> Definir(Rol rol) =>
64	        rol == Rol.Coordinador ? HerramientasDeCoordinador : HerramientasDeEstudiante;
65	
66	    public async Task<ResultadoHerramienta> EjecutarAsync(
67	        LlamadaHerramienta llamada,
68	        ContextoUsuario contexto,
69	        RegistroConsultas registro,
70	        CancellationToken cancellationToken)
71	    {
72	        if (!EstaDisponible(llamada.Nombre, contexto.Usuario.Rol) || !_manejadores.TryGetValue(llamada.Nombre, out var manejador))
73	        {
74	            return ResultadoHerramienta.Texto(Textos.HerramientaNoDisponible);
75	        }
76	
77	        var estudianteId = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroEstudianteId);
78	        if (EsLecturaAjena(contexto, estudianteId))
79	        {
80	            return ResultadoHerramienta.Denegado(IdAuditable(estudianteId));
81	        }
82	
83	        var asignatura = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroAsignatura);
84	        return await manejador(new SolicitudHerramienta(contexto, registro, estudianteId, asignatura, cancellationToken));
85	    }
86	
87	    private static string IdAuditable(string? idSolicitado) =>
88	        idSolicitado is not null && (Identificadores.EsIdEstudiante(idSolicitado) || Identificadores.EsIdCoordinador(idSolicitado))
89	            ? idSolicitado
90	            : Textos.FormatoInvalido;
91	
92	    private static bool EstaDisponible(string nombre, Rol rol) =>
93	        Definir(rol).Any(herramienta => herramienta.Nombre == nombre);
94	
95	    private bool EsLecturaAjena(ContextoUsuario contexto, string? estudianteId) =>
96	        estudianteId is not null
97	        && !_politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, estudianteId, contexto.Directorio).Permitido;
98	
99	    private Task<ResultadoHerramienta> ConsultarDatosBasicos(SolicitudHerramienta solicitud)
100	    {
101	        var estudiante = solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == solicitud.Contexto.Usuario.Id);
102	        var contenido = FormateadorDatos.DatosBasicos(estudiante, solicitud.Contexto.Directorio);
103	        solicitud.Registro.RegistrarDatos([DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, RecursoConsultado.DatosBasicos)]);
104	        return Task.FromResult(Responder(solicitud, contenido, estudiante.Id, [RecursoConsultado.DatosBasicos], Textos.SeccionDatosBasicos));
105	    }
106	
107	    private async Task<ResultadoHerramienta> ConsultarNotas(SolicitudHerramienta solicitud)
108	    {
109	        var id = solicitud.Contexto.Usuario.Id;
110	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
111	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
112	        solicitud.Registro.RegistrarResumen(resumen);
113	        return Responder(solicitud, ConReglas(solicitud, FormateadorDatos.Notas(resumen), ReglasAplicadas.DeNotas([resumen])), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionNotas);
114	    }
115	
116	    private async Task<ResultadoHerramienta> ConsultarCortes(SolicitudHerramienta solicitud)
117	    {
118	        if (string.IsNullOrWhiteSpace(solicitud.Asignatura))
119	        {
120	            return ResultadoHerramienta.Texto(Textos.FaltaAsignatura);
121	        }
122	
123	        var id = solicitud.Contexto.Usuario.Id;
124	        var notas = await _apiAcademica.ObtenerNotasAsync(id, solicitud.CancellationToken);
125	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
126	        var contenido = ConReglas(solicitud, FormateadorDatos.Cortes(notas, solicitud.Asignatura), ReglasAplicadas.DeNotas([resumen]));
127	        var codigos = FormateadorDatos.BuscarAsignaturas(notas, solicitud.Asignatura).Select(nota => nota.Codigo);
128	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorCodigos(id, ProgramaDe(solicitud, id), codigos, RecursoConsultado.Notas));
129	        return Responder(solicitud, contenido, id, [RecursoConsultado.Notas], Textos.SeccionNotas);
130	    }
131	
132	    private async Task<ResultadoHerramienta> ConsultarAsistencia(SolicitudHerramienta solicitud)
133	    {
134	        var id = solicitud.Contexto.Usuario.Id;
135	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
136	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
137	        solicitud.Registro.RegistrarResumen(resumen);
138	        return Responder(solicitud, ConReglas(solicitud, FormateadorDatos.Asistencia(resumen), ReglasAplicadas.DeAsistencia([resumen])), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionAsistencia);
139	    }
140	
141	    private async Task<ResultadoHerramienta> ConsultarEstudiante(SolicitudHerramienta solicitud)
142	    {
143	        if (string.IsNullOrEmpty(solicitud.EstudianteId))
144	        {
145	            return ResultadoHerramienta.Texto(Textos.FaltaIdentificadorEstudiante);
146	        }
147	
148	        var directorio = solicitud.Contexto.Directorio;
149	        var estudiante = directorio.Estudiantes.First(e => e.Id == solicitud.EstudianteId);
150	        var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
151	        var detalle = string.Join("\n", FormateadorDatos.DatosBasicos(estudiante, directorio), FormateadorDatos.Notas(resumen), FormateadorDatos.Asistencia(resumen, terceraPersona: true));
152	        var contenido = ConReglas(solicitud, detalle, ReglasAplicadas.DeNotasYAsistencia([resumen]));
153	        var recursos = new[] { RecursoConsultado.DatosBasicos, RecursoConsultado.Notas, RecursoConsultado.Asistencia };
154	        solicitud.Registro.Registrar(estudiante.Id, recursos, new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionAsistencia));
155	        solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.DatosBasicos));
156	        solicitud.Registro.RegistrarResumen(resumen);
157	        return Responder(solicitud, contenido, estudiante.Id, recursos, Textos.SeccionNotas);
158	    }
159	
160	    public async Task<string> LeerProgramaAsync(ContextoUsuario contexto, RegistroConsultas registro, CancellationToken cancellationToken)
161	    {
162	        var resultado = await ConsultarPrograma(new SolicitudHerramienta(contexto, registro, null, null, cancellationToken));
163	        registro.AgregarFuente(resultado.Contenido);
164	        return resultado.Contenido;
165	    }
166	
167	    private async Task<ResultadoHerramienta> ConsultarPrograma(SolicitudHerramienta solicitud)
168	    {
169	        var programas = _politicaAcceso.ProgramasAutorizados(solicitud.Contexto.Usuario, solicitud.Contexto.Directorio);
170	        if (programas.Count == 0)
171	        {
172	            return ResultadoHerramienta.Texto(Textos.SinProgramasAsignados);
173	        }
174	
175	        var bloques = new List<string>();
176	        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
177	        {
178	            bloques.Add(await DescribirProgramaAsync(solicitud, programa));
179	        }
180	
181	        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
182	    }
183	
184	    private async Task<string> DescribirProgramaAsync(SolicitudHerramienta solicitud, Programa programa)
185	    {
186	        var estudiantes = solicitud.Contexto.Directorio.Estudiantes.Where(e => e.ProgramaId == programa.Id).ToList();
187	        var datos = new List<EstudianteDePrograma>();
188	        var resumenes = new List<ResumenEstudiante>();
189	        foreach (var estudiante in estudiantes)
190	        {
191	            var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
192	            resumenes.Add(resumen);
193	            datos.Add(new EstudianteDePrograma(estudiante, resumen));
194	            solicitud.Registro.Registrar(estudiante.Id, [RecursoConsultado.Programa, RecursoConsultado.Notas, RecursoConsultado.Asistencia], null);
195	            solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.Programa));
196	            solicitud.Registro.RegistrarResumen(resumen);
197	        }
198	
199	        solicitud.Registro.RegistrarCita(new Cita(Textos.DocumentoDatosPrograma, programa.Id));
200	        var contenido = ConReglas(solicitud, FormateadorPrograma.Bloque(programa, datos), ReglasAplicadas.DePrograma(resumenes));
201	        return FormateadorDatos.Delimitar($"{Textos.DocumentoDatosPrograma} · {programa.Id}", contenido);
202	    }
203	
204	    private static string ProgramaDe(SolicitudHerramienta solicitud, string estudianteId) =>
205	        solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == estudianteId).ProgramaId;
206	
207	    private static IEnumerable<DatoConsultado> DatosDeEstudiante(Estudiante estudiante, ResumenEstudiante resumen, RecursoConsultado recursoSinAsignatura) =>
208	        DatosLeidos.PorAsignatura(resumen, estudiante.ProgramaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia)
209	            .Prepend(DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, recursoSinAsignatura));
210	
211	    private static string ConReglas(SolicitudHerramienta solicitud, string contenido, IReadOnlyList<int> entradas)
212	    {
213	        solicitud.Registro.RegistrarReglas(entradas);
214	        var reglas = ReglasAplicadas.Citas(entradas);
215	        return reglas.Count == 0 ? contenido : $"{contenido}\n{FormateadorResumen.LineaDeReglas(reglas)}";
216	    }
217	
218	    private static ResultadoHerramienta Responder(
219	        SolicitudHerramienta solicitud,
220	        string contenido,
221	        string estudianteId,
222	        IEnumerable<RecursoConsultado> recursos,
223	        string seccion)
224	    {
225	        var cita = new Cita(Textos.DocumentoDatosEstudiante, seccion);
226	        solicitud.Registro.Registrar(estudianteId, recursos, cita);
227	        return ResultadoHerramienta.Texto(FormateadorDatos.Delimitar($"{cita.Documento} · {cita.Seccion}", contenido));
228	    }
229	
230	    private Task<ResumenEstudiante> ResumirAsync(string estudianteId, CancellationToken cancellationToken) =>
231	        ResumenesAcademicos.ResumirAsync(_apiAcademica, estudianteId, cancellationToken);
232	
233	    private sealed record SolicitudHerramienta(
234	        ContextoUsuario Contexto,
235	        RegistroConsultas Registro,
236	        string? EstudianteId,
237	        string? Asignatura,
238	        CancellationToken CancellationToken);
239	}
