namespace Sonda;

public sealed class SondaHerr
{
    static ClienteLlmDoble Pide(string herramienta, string args) =>
        new((s, n) => n == 0
            ? new RespuestaLlm(null, [new LlamadaHerramienta("x1", herramienta, args)], ClienteLlmDoble.UsoPorDefecto, false)
            : new RespuestaLlm(ClienteLlmDoble.EcoDeHerramientas(s), [], ClienteLlmDoble.UsoPorDefecto, false));

    public static readonly (string, string, string, string, string, string)[] Casos =
    [
        ("H1","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":\"EST-005\"}"),
        ("H2","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":\"est-005\"}"),
        ("H3","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":\"EST-002\",\"estudianteId\":\"EST-005\"}"),
        ("H4","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":\"EST-005\",\"estudianteId\":\"EST-002\"}"),
        ("H5","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":\"../programas/ADM/estudiantes\"}"),
        ("H6","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":[\"EST-005\"]}"),
        ("H7","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"EstudianteId\":\"EST-005\"}"),
        ("H8","coordinador","COORD-01","¿Cómo va Valentina?","consultar_estudiante","{\"estudianteId\":\"EST-0\\u0030\\u0035\"}"),
        ("H9","coordinador","COORD-01","¿Cómo va Valentina?","consultar_notas","{}"),
        ("H10","coordinador","COORD-01","¿Cómo va Valentina?","consultar_programa","{\"programaId\":\"ADM\"}"),
        ("H11","estudiante","EST-001","¿Cuál es mi promedio?","consultar_notas","{\"estudianteId\":\"EST-002\"}"),
        ("H12","estudiante","EST-001","¿Cuál es mi promedio?","consultar_estudiante","{\"estudianteId\":\"EST-002\"}"),
        ("H13","estudiante","EST-001","¿Cuál es mi promedio?","consultar_programa","{}"),
        ("H14","estudiante","EST-001","¿Cuál es mi promedio?","consultar_cortes","{\"asignatura\":\"EST-102\"}"),
        ("H15","estudiante","EST-001","¿Cuál es mi promedio?","consultar_cortes","{\"asignatura\":\"Microeconomía\"}"),
        ("H16","estudiante","EST-001","¿Cuál es mi promedio?","consultar_notas","{\"estudianteId\":\"EST-001\"}"),
        ("H17","coordinador","COORD-01","¿Cómo va Andrés Martínez?","consultar_estudiante","{\"estudianteId\":\"EST-002\"}"),
